import React, { useEffect, useState } from "react";
import { useLocation, useNavigate } from "react-router-dom";
import Header from "../components/header";
import Footer from "../components/footer";
import "./Results.css";

const Results = () => {
  const location = useLocation();
  const navigate = useNavigate();

  // ✅ Query search OR image search dono support
  const query = location.state?.query || "";
  const productsFromState = location.state?.products || [];

  const [products, setProducts] = useState(productsFromState);
  const [loading, setLoading] = useState(true);
  const [sortBy, setSortBy] = useState("default");

  const [favorites, setFavorites] = useState([]);
  const [user, setUser] = useState(null);

  // ✅ Load user
  useEffect(() => {
    const storedUser = JSON.parse(
      localStorage.getItem("user")
    );

    setUser(storedUser);
  }, []);

  // ✅ Load favorites
  useEffect(() => {
    if (!user) return;

    fetch(`http://localhost:5000/favorites/${user.email}`)
      .then((res) => res.json())
      .then((data) => {
        setFavorites(data);

        localStorage.setItem(
          `favorites_${user.email}`,
          JSON.stringify(data)
        );
      })
      .catch((err) => console.log(err));

  }, [user]);

  // ✅ TEXT SEARCH FETCH
  useEffect(() => {

    // agar image search se products aaye hain
    if (productsFromState.length > 0) {
      setLoading(false);
      return;
    }

    const fetchData = async () => {
      if (!query) {
        setLoading(false);
        return;
      }

      try {
        const response = await fetch(
          `http://localhost:5000/api/search?q=${query}`
        );

        const data = await response.json();

        const results =
          data?.shopping_results ||
          data?.organic_results ||
          data?.inline_shopping_results ||
          [];

        const formatted = results
          .slice(0, 40)
          .map((item) => ({
            title: item.title || "No Title",
            price: item.price || "N/A",
            rating: item.rating || "3.5",

            thumbnail:
              item.thumbnail ||
              item.image ||
              "",

            link:
              item.link ||
              item.product_link ||
              item.offer_link ||
              item.source_link ||
              "#",

            source:
              item.source || "Unknown",

            reviews: item.reviews || null,
          }));

        setProducts(formatted);

      } catch (error) {
        console.log("ERROR:", error);

      } finally {
        setLoading(false);
      }
    };

    fetchData();

  }, [query, productsFromState]);

  // ✅ Check favorite
  const isFavorite = (product) => {
    return favorites.some(
      (item) => item.link === product.link
    );
  };

  // ✅ Toast
  const showToast = (message) => {

    const toast = document.createElement("div");

    toast.innerText = message;
    toast.className = "toast";

    document.body.appendChild(toast);

    setTimeout(() => {
      toast.remove();
    }, 2000);
  };

  // ✅ Favorite Toggle
  const toggleFavorite = async (product) => {

    if (!user) {
      showToast("⚠️ Please Sign In first!");
      return;
    }

    try {

      const existing = favorites.find(
        (item) => item.link === product.link
      );

      // REMOVE
      if (existing) {

        await fetch(
          `http://localhost:5000/favorites/${existing._id}`,
          {
            method: "DELETE",
          }
        );

        const updated = favorites.filter(
          (item) => item.link !== product.link
        );

        setFavorites(updated);

        localStorage.setItem(
          `favorites_${user.email}`,
          JSON.stringify(updated)
        );

        showToast("Removed from favorites ❌");

      } else {

        // ADD
        const response = await fetch(
          "http://localhost:5000/favorites",
          {
            method: "POST",

            headers: {
              "Content-Type": "application/json",
            },

            body: JSON.stringify({
              userEmail: user.email,

              title: product.title,
              price: product.price,
              rating: product.rating,

              image:
                product.thumbnail || "",

              link: product.link,
              source: product.source,
            }),
          }
        );

        const data = await response.json();

        const updated = [
          ...favorites,
          data,
        ];

        setFavorites(updated);

        localStorage.setItem(
          `favorites_${user.email}`,
          JSON.stringify(updated)
        );

        showToast("Added to favorites ⭐");
      }

    } catch (error) {
      console.log(error);
    }
  };

  // ✅ Rating Stars
  const renderStars = (rating) => {

    if (!rating) return null;

    const num = parseFloat(rating);

    const full = Math.floor(num);

    const half = num % 1 >= 0.5;

    const empty = 5 - full - (half ? 1 : 0);

    return (
      <span className="stars">
        {"★".repeat(full)}
        {half ? "½" : ""}
        {"☆".repeat(empty)}

        <span className="rating-num">
          {num.toFixed(1)}
        </span>
      </span>
    );
  };

  // ✅ Sorting
  const sorted = [...products].sort((a, b) => {

    if (sortBy === "price-low") {

      const pa =
        parseFloat(
          a.price?.replace(/[^0-9.]/g, "")
        ) || 9999;

      const pb =
        parseFloat(
          b.price?.replace(/[^0-9.]/g, "")
        ) || 9999;

      return pa - pb;
    }

    if (sortBy === "price-high") {

      const pa =
        parseFloat(
          a.price?.replace(/[^0-9.]/g, "")
        ) || 0;

      const pb =
        parseFloat(
          b.price?.replace(/[^0-9.]/g, "")
        ) || 0;

      return pb - pa;
    }

    if (sortBy === "rating") {

      const ra =
        parseFloat(a.rating) || 0;

      const rb =
        parseFloat(b.rating) || 0;

      return rb - ra;
    }

    return 0;
  });

  return (
    <>
      <Header />

      <div className="results-page">

        {/* HERO */}
        <div className="hero">

          <p className="hero-label">
            Search Results
          </p>

          <h1 className="hero-title">
            We found <span>{products.length}</span>
            <br />
            matches for you
          </h1>

          <p className="hero-sub">
            Compare prices across multiple stores and grab the best deal.
          </p>

        </div>

        {loading ? (

          <p style={{ padding: "40px" }}>
            Loading...
          </p>

        ) : products.length === 0 ? (

          <div className="empty-state">

            <div className="empty-icon">
              🔍
            </div>

            <h3>No results found</h3>

            <p>
              Try a different description or image.
            </p>

            <button
              className="try-again-btn"
              onClick={() => navigate(-1)}
            >
              Try Again
            </button>

          </div>

        ) : (

          <>
            {/* CONTROLS */}
            <div className="controls">

              <span className="sort-label">
                Sort by:
              </span>

              {[
                "default",
                "price-low",
                "price-high",
                "rating",
              ].map((opt) => (

                <button
                  key={opt}

                  className={`sort-btn ${
                    sortBy === opt
                      ? "active"
                      : ""
                  }`}

                  onClick={() =>
                    setSortBy(opt)
                  }
                >
                  {opt === "default" &&
                    "Default"}

                  {opt === "price-low" &&
                    "Price: Low to High"}

                  {opt === "price-high" &&
                    "Price: High to Low"}

                  {opt === "rating" &&
                    "⭐ Top Rated"}
                </button>
              ))}

              <div className="count-badge">
                <span>{products.length}</span>{" "}
                results
              </div>

            </div>

            {/* GRID */}
            <div className="products-grid">

              {sorted.map((product, i) => (

                <div
                  className="product-card"
                  key={i}

                  style={{
                    animationDelay: `${i * 60}ms`,
                  }}
                >

                  <div className="card-img-wrap">

                    {product.thumbnail ? (

                      <img
                        src={product.thumbnail}
                        alt={product.title}
                      />

                    ) : (

                      <div className="no-img">
                        🛍️
                      </div>
                    )}

                    {product.source && (
                      <span className="source-badge">
                        {product.source}
                      </span>
                    )}

                  </div>

                  <div className="card-body">

                    <p className="card-title">
                      {product.title ||
                        "Product"}
                    </p>

                    {product.rating && (
                      <>
                        {renderStars(
                          product.rating
                        )}

                        {product.reviews && (
                          <p className="reviews-count">
                            {product.reviews} reviews
                          </p>
                        )}
                      </>
                    )}

                    <div className="card-footer">

                      {product.price ? (
                        <span className="price">
                          {product.price}
                        </span>
                      ) : (
                        <span className="price no-price">
                          Price N/A
                        </span>
                      )}

                      <div
                        style={{
                          display: "flex",
                          gap: "8px",
                          alignItems: "center",
                        }}
                      >

                        {/* ⭐ Favorite */}
                        <button
                          onClick={() =>
                            toggleFavorite(product)
                          }

                          style={{
                            background:
                              "transparent",

                            border: "none",

                            fontSize: "22px",

                            cursor: "pointer",

                            color: isFavorite(product)
                              ? "#f0b429"
                              : "#888",
                          }}
                        >
                          {isFavorite(product)
                            ? "★"
                            : "☆"}
                        </button>

                        {/* 🌐 Website Link */}
                        {product.link && (
                          <button
                            className="visit-btn"

                            onClick={() => {

                              if (
                                product.link &&
                                product.link !== "#"
                              ) {

                                window.location.href =
                                  `/redirect?url=${encodeURIComponent(
                                    product.link
                                  )}`;

                              } else {

                                alert(
                                  "Link not available"
                                );
                              }
                            }}
                          >
                            Visit →
                          </button>
                        )}

                      </div>

                    </div>

                  </div>

                </div>
              ))}

            </div>
          </>
        )}

      </div>

      <Footer />
    </>
  );
};

export default Results;
